import{_ as e,o as t,c as s,ae as n}from"./chunks/framework.Co1PSFSm.js";const h=JSON.parse('{"title":"Arquitectura del Sistema","description":"","frontmatter":{},"headers":[],"relativePath":"arquitectura/index.md","filePath":"arquitectura/index.md","lastUpdated":null}'),d={name:"arquitectura/index.md"};function o(c,a,r,i,l,p){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="arquitectura-del-sistema" tabindex="-1">Arquitectura del Sistema <a class="header-anchor" href="#arquitectura-del-sistema" aria-label="Permalink to &quot;Arquitectura del Sistema&quot;">​</a></h1><h2 id="clean-architecture" tabindex="-1">Clean Architecture <a class="header-anchor" href="#clean-architecture" aria-label="Permalink to &quot;Clean Architecture&quot;">​</a></h2><p>El proyecto sigue una arquitectura limpia en capas:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP (Controllers) → Use Cases → Domain Services → Models (Eloquent)</span></span></code></pre></div><h3 id="capas" tabindex="-1">Capas <a class="header-anchor" href="#capas" aria-label="Permalink to &quot;Capas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capa</th><th>Responsabilidad</th><th>Directorio</th></tr></thead><tbody><tr><td><strong>Controllers</strong></td><td>Validación HTTP, respuesta, inyección de dependencias</td><td><code>app/Http/Controllers/</code></td></tr><tr><td><strong>Use Cases</strong></td><td>Orquestar lógica de negocio, coordinar servicios</td><td><code>app/Application/UseCases/</code></td></tr><tr><td><strong>Domain Services</strong></td><td>Lógica de negocio pura, consultas a BD con caché</td><td><code>app/Domain/Services/</code></td></tr><tr><td><strong>Value Objects</strong></td><td>Objetos de valor inmutables (Filtros, Períodos)</td><td><code>app/Domain/ValueObjects/</code></td></tr><tr><td><strong>Models</strong></td><td>Eloquent ORM, relationships, accesors</td><td><code>app/Models/</code></td></tr></tbody></table><h3 id="flujo-de-una-peticion-tipica" tabindex="-1">Flujo de una Petición Típica <a class="header-anchor" href="#flujo-de-una-peticion-tipica" aria-label="Permalink to &quot;Flujo de una Petición Típica&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Request HTTP → Controller</span></span>
<span class="line"><span>2. Controller construye Value Objects desde request</span></span>
<span class="line"><span>3. Controller llama Use Case</span></span>
<span class="line"><span>4. Use Case llama Domain Service</span></span>
<span class="line"><span>5. Domain Service consulta Models (con caché)</span></span>
<span class="line"><span>6. Datos retornan → Controller → View</span></span></code></pre></div><h2 id="diagrama-de-modulos" tabindex="-1">Diagrama de Módulos <a class="header-anchor" href="#diagrama-de-modulos" aria-label="Permalink to &quot;Diagrama de Módulos&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dashboard</span></span>
<span class="line"><span>  └── DashboardService (índice de eficiencia)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Estado de Resultados</span></span>
<span class="line"><span>  ├── ERDomainService (consulta metas ER)</span></span>
<span class="line"><span>  └── PDFERExtractorService (extracción de PDF)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POA</span></span>
<span class="line"><span>  ├── POADomainService (cálculo de metas vs real, consolidado)</span></span>
<span class="line"><span>  ├── POAExportService (descarga Excel/PDF)</span></span>
<span class="line"><span>  └── SincronizarPOA (sincronización desde ER)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Importaciones</span></span>
<span class="line"><span>  ├── ERSheetImport (Excel META por hoja/almacén)</span></span>
<span class="line"><span>  ├── VentasDetalladasImport (Excel REAL por línea de producto)</span></span>
<span class="line"><span>  ├── SurtimientoTiendasImport (Excel REAL oportunidad/eficiencia)</span></span>
<span class="line"><span>  └── MermasQuebrantosImport (Excel META tasas sobre ventas)</span></span></code></pre></div><h2 id="estrategia-de-cache" tabindex="-1">Estrategia de Caché <a class="header-anchor" href="#estrategia-de-cache" aria-label="Permalink to &quot;Estrategia de Caché&quot;">​</a></h2><p>Todas las consultas pesadas se cachean con <code>Cache::remember()</code>:</p><table tabindex="0"><thead><tr><th>Clave</th><th>TTL</th><th>Propósito</th></tr></thead><tbody><tr><td><code>almacenes_ordenados</code></td><td>24h</td><td>Lista de almacenes</td></tr><tr><td><code>conceptos_poa</code></td><td>24h</td><td>Conceptos categoría POA</td></tr><tr><td><code>conceptos_er</code></td><td>24h</td><td>Conceptos categoría ER</td></tr><tr><td><code>conceptos_er_pluck</code></td><td>24h</td><td>Pluck de conceptos ER</td></tr><tr><td><code>conceptos_lp_ids</code></td><td>24h</td><td>IDs de líneas de producto</td></tr><tr><td><code>poa_data_{...}</code></td><td>5min</td><td>Datos POA calculados</td></tr><tr><td><code>er_data_{...}</code></td><td>5min</td><td>Datos ER calculados</td></tr><tr><td><code>dashboard_data_{...}</code></td><td>5min</td><td>Dashboard</td></tr></tbody></table><p><strong>Invalidación</strong>: Cada import incrementa <code>poa_cache_version</code>, lo que cambia la clave de caché de datos calculados (POA, ER, Dashboard).</p>`,14)])])}const m=e(d,[["render",o]]);export{h as __pageData,m as default};
